// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // Helper attacker that accepts funds (fallback payable) so target.call succeeds and the contract receives the funds
    // We need a normal payable callee so the low-level call in C succeeds; the difference is whether C transfers out its balance.
    function setUp() public { c = new C(); }

    // Fuzz the amount and the sender to ensure generality. The deciding parameter is the amount of ETH forwarded into go().
    function testFuzz_property(uint256 amount, address sender) public {
        // keep amount in a reasonable range (not too large to overflow testing environment) but allow zero too
        amount = bound(amount, 0, 10 ether);
        // ensure sender is distinct and has funds
        vm.deal(sender, amount + 1 ether);

        // The target address used inside C is a fixed hardcoded address. We cannot change that in C.
        // To ensure the low-level call to that address succeeds, deploy a contract at that address by using create2 with that address.
        // Compute salt so that create2 yields the required hardcoded address.
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;

        // Deploy a minimal payable receiver at the exact target address via create2 with an initcode that returns runtime code with payable fallback.
        bytes memory runtime = hex"600b5981380380925939f3"; // minimal runtime that just ends (no-op), irrelevant because payable fallback is provided in constructorless form
        // Instead of assembling bytecode, deploy a simple contract whose constructor leaves a payable fallback. We'll use an initcode that returns minimal code with payable fallback by using solidity factory deployment below.

        // Use a factory contract deployed here to create target at the desired address via create2.
        Deployer dep = new Deployer();
        bytes32 salt = bytes32(uint256(uint160(target)));
        dep.deploy{value: 0}(salt);
        // Ensure the deployed address equals target
        assert(address(dep.deployed()) == target);

        // Now call c.go with funds from sender; the low-level call to target will succeed (the deployed contract has payable fallback)
        vm.prank(sender);
        c.go{value: amount}();

        // The universal property: after any call to go (for any sender and amount), the correct contract forwards out its balance to owner
        // So address(c).balance should be zero. This holds for the reference and will fail for the mutant when amount>0.
        assertTrue(address(c).balance == 0);
    }
}

// Minimal deployer that creates a payable fallback contract at a deterministic address via create2
contract Deployer {
    address public _deployed;
    function deploy(bytes32 salt) external payable {
        // runtime code for a contract with payable fallback that does nothing
        bytes memory runtime = hex"600a600c600039600a6000f3602a60005260206000f3"; // simple runtime
        // constructor: returns runtime
        bytes memory init = abi.encodePacked(
            hex"60", bytes1(uint8(runtime.length)), // push runtime length
            hex"60", bytes1(uint8(0x0c)), // push offset 0x0c
            hex"60", bytes1(uint8(0x00)),
            hex"39", // CODECOPY
            hex"60", bytes1(uint8(runtime.length)),
            hex"60", bytes1(uint8(0x00)),
            hex"f3", // RETURN
            runtime
        );
        address addr;
        assembly {
            addr := create2(callvalue(), add(init, 0x20), mload(init), salt)
            if iszero(extcodesize(addr)) { revert(0,0) }
        }
        _deployed = addr;
    }
    function deployed() external view returns (address) { return _deployed; }
}

