pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the amount and the caller address. The adversarial counterparty is a normal payable address
    // (an EOA) because in this scenario C calls a fixed target address; to simulate that call succeeding
    // and forwarding value, it's sufficient that the target does not revert. The distinguishing observable
    // is address(c).balance after calling go(). The reference should always leave balance 0; the mutant may not.
    function testFuzz_property(uint256 amount, address caller) public {
        // keep amount in a reasonable range for sending from caller
        amount = bound(amount, 0, 1 ether);
        // caller must be nonzero
        vm.assume(caller != address(0));

        // Fund caller so it can send amount
        vm.deal(caller, amount);
        vm.prank(caller);
        // Call go with value = amount
        // wrap in try/catch to allow both success and revert, but reference should not revert
        bool ok;
        try c.go{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after go returns (whether success or not), the reference C ensures its
        // contract balance is zero (it forwards funds to owner). We assert that address(c).balance == 0.
        // This is a single assertion reading c's public surface (address(c).balance).
        assertTrue(address(c).balance == 0);
    }
}

