pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the amount and the caller. Deploy a helper callee that accepts ETH so the low-level call succeeds.
    function testFuzz_property(uint256 amount, address caller) public {
        // keep amount within reasonable bounds and non-zero to allow distinguishing behavior
        amount = bound(amount, 0, 1 ether);
        // allow caller to be any address but avoid the zero address as an EOA sender
        if (caller == address(0)) caller = address(1);

        // Fund the caller so they can send ETH
        vm.deal(caller, amount);

        // The target in C is a hardcoded address. We deploy a simple AcceptAll helper and
        // place its address at that hardcoded location using create2 is not available here.
        // Instead, we emulate the scenario by calling go() from the helper via a relay: since
        // the low-level call in C is to a fixed address, to make that call succeed we must
        // ensure the fixed address has code and a payable fallback/receive. We accomplish
        // this by deploying a helper at that exact address using a pre-funded contract deployment.
        // However, we cannot deterministically deploy at an arbitrary address here, so instead
        // we rely on the fact that the reference contract's call will succeed only when the
        // callee accepts ETH; to create such an accepting callee at the fixed address below,
        // we use a small trick: the hardcoded address used by C in the exercise is 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;
        // we deploy an AcceptAll and then use vm.etch to give that address code. vm.etch is not
        // permitted by the problem statement, so instead we deploy a helper and then call c.go
        // expecting success when the low-level call returns true. The test then asserts the
        // invariant on address(c).balance which the correct contract guarantees to be zero.

        // Deploy a simple accepting contract and ensure it can be used as the target by making
        // the test scenario where the low-level call in C succeeds. The minimal requirement is
        // that the call returns true; since the hardcoded address in C cannot be changed here,
        // we instead proceed with the admissible domain: the property we assert is that after
        // calling go with any msg.value the correct contract ends with zero balance when the
        // external call succeeds. To make the external call succeed we rely on the environment
        // where the low-level call to the hardcoded address (if it exists) will succeed; the
        // fuzzer will still find inputs (amount>0) where the mutant leaves funds in the contract.

        // Perform the call as the fuzzed caller sending the fuzzed amount
        if (amount == 0) {
            // If amount is zero, both contracts behave the same (no funds forwarded). Keep admissible domain wide: allow zero but it won't distinguish mutant. We still run it.
            vm.prank(caller);
            c.go{value: 0}();
        } else {
            vm.prank(caller);
            // send the fuzzed amount
            (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("go()"));
            // ignore ok here; the assertion below examines contract balance
        }

        // The universal property: after any admissible call with any msg.value, the correct contract
        // ends with zero balance. The mutant that transfers 0 can leave a nonzero balance for some inputs.
        // Assert that c's balance is zero. This holds for the reference for all inputs, and the mutant
        // will fail for some fuzzed inputs (the fuzzer will find them).
        assertTrue(address(c).balance == 0);
    }
}

