import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    // attacker address that will call C.go
    address payable sender = payable(address(0xABCD));

    function setUp() public { c = new C(); }

    // fuzz the amount sent to go; the adversarial callee (Reverter) will always revert when called
    function testFuzz_property(uint256 amt) public {
        // keep amount in sensible range but wide
        amt = bound(amt, 1, 1 ether);

        // deploy a callee that always reverts on receive/call
        Reverter rev = new Reverter();

        // fund sender
        vm.deal(sender, amt);

        // make C use the Reverter address as the hard-coded target by using the same address
        // Since C has target hard-coded in source, we cannot change it; instead this test exercises
        // the behavior by making the hard-coded target address point to our Reverter by deploying
        // it at that address via vm.prank/deploy is not allowed. Instead we ensure the observed universal
        // property is about c.balance after calling go: when the external call to target reverts,
        // the reference will have forwarded funds out, leaving c.balance == 0. The mutant calling with value 0
        // will keep funds in c, making c.balance == amt. To force the external call to revert at the hardcoded
        // target address, we emulate its behavior by deploying a Reverter at that address using create2.

        // compute the hardcoded target address from C source
        address target = 0xC8A60C51967F4022BF9424C337e9c6F0bD220E1C;

        // Deploy a Reverter at the exact target address using create2
        // We construct creation code for Reverter and use create2 with salt 0
        bytes memory bytecode = type(Reverter).creationCode;
        bytes32 salt = bytes32(uint256(uint160(target)));
        address deployed;
        assembly {
            deployed := create2(0, add(bytecode, 32), mload(bytecode), salt)
        }
        // ensure deployed is at target
        require(deployed == target, "deploy failed");

        // send transaction from sender to c.go with amt value
        vm.prank(sender);
        // call c.go{value: amt}()
        (bool ok,) = address(c).call{value: amt}(abi.encodeWithSignature("go()"));

        // The general property: after calling go with a callee that reverts on any incoming value,
        // the reference forwards the ETH to owner, leaving c.balance == 0. The mutant that sends zero
        // to target will keep the ETH in c, producing c.balance > 0 for some input (amt).
        // Assert the universal fact that c.balance == 0 for all valid amt when the callee reverts.
        assertTrue(address(c).balance == 0);
    }
}

