pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public { c = new C(); owner = address(uint160(uint256(keccak256("owner")))); }

    // Fuzzed parameters: caller address and amount sent to go
    function testFuzz_property(address caller, uint256 amount) public {
        // Keep domain reasonable: caller must not be zero address and amount bounded to avoid overflow in vm.deal
        vm.assume(caller != address(0));
        amount = bound(amount, 0, 1 ether);

        // Deploy a benign target that accepts funds so the external call from C succeeds.
        // This ensures behavior is the 'successful external call' branch.
        AcceptAll target = new AcceptAll();

        // We need C to call that target address; since C has the target address hardcoded in source,
        // we cannot change it here. Instead, we make the hardcoded address behave like an EOA that accepts funds.
        // To do that in Foundry tests we can fund that address and deploy a minimal contract at that address via
        // create2 with known salt until we get the address — but simpler: since the hardcoded address is a concrete
        // address, we cannot deploy code there in test environment. However, low-level calls to EOAs succeed,
        // and the reference expects to forward msg.value to the target. The original instructions note that calls to
        // EOAs always succeed; to ensure the external call succeeds, we can pick inputs such that the call does not revert.
        // The call in C is to a fixed address; in the EVM test env that call will return success (as call to EOA).
        // Therefore no special adversary contract is necessary here.

        // Record owner's balance before
        vm.deal(owner, 0);
        uint256 ownerBefore = owner.balance;

        // Fund the caller so it can send amount
        vm.deal(caller, amount);

        // Make the call from caller to c.go sending amount
        vm.prank(caller);
        // call and ignore revert possibility; if it reverts, we consider that behavior as not increasing owner
        try c.go{value: amount}() {
            // call succeeded
        } catch {
            // if c.go reverted, then owner cannot have been paid — but the reference should not revert for admissible inputs
        }

        // After go() returns (and assuming the external call succeeded), the reference contract forwards its full remaining
        // balance to owner, which in this setup equals the msg.value forwarded through c. Thus owner balance should have
        // increased by exactly amount.
        uint256 ownerAfter = owner.balance;

        // Single assertion reading c's observable behavior via owner's balance change
        assertTrue(ownerAfter - ownerBefore == amount);
    }
}

// Minimal helper that accepts any funds
contract AcceptAll {
    receive() external payable {}
}
